/** Tracks a user might pick, with their steps in order. */
export function trackSteps(trackId: string): LibraryItem[] {
  return TRACK_ITEMS.filter((i) => i.track === trackId).sort((a, b) => (a.step ?? 0) - (b.step ?? 0));
}
